WITH recent_web_events AS (SELECT * FROM web_events WHERE TO_DATE(event_time) < '2024-09-30'), web_events_stats AS (SELECT page, HOUR(event_time) AS event_hour, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, MIN(duration_sec) AS min_duration_sec FROM recent_web_events GROUP BY page, HOUR(event_time)) SELECT * FROM web_events_stats WHERE min_duration_sec < 180 ORDER BY page_values;
